-- Replace editorial notes and unanswered prompt lists with explanatory lesson content.
-- Sources: OpenStax Introduction to Philosophy and Psychology; Stanford Encyclopedia
-- of Philosophy (knowledge analysis, panpsychism); Gettier, Analysis 23 (1963).
-- Existing lesson identities and progress are preserved; published versions are immutable.
do $migration$
declare
 v_row jsonb; v_lesson uuid; v_old public.lesson_versions; v_new uuid; v_actor uuid;
begin
 select user_id into v_actor from public.user_roles where role='admin' order by user_id limit 1;
 for v_row in select value from jsonb_array_elements($content$[{"title": "Philosophers on education", "objective": "Match each definition of education to Dayananda, Gandhi, Aristotle, Ellen G. White, Socrates or Dewey.", "blocks": [{"text": "These thinkers emphasise different aims of education, including character, personal growth and practical experience.", "type": "paragraph"}, {"items": ["Dayananda, Swami (1824-1883) defined education as the formation of character.", "Gandhi, M.K. (1869-1948) defined education as the all-round drawing out of the best.", "Aristotle (384-322) defined education as the creation of a sound mind in a sound body.", "Ellen G. White (1824-1915) defined education as the harmonious development of the physical, mental and spiritual powers.", "Socrates defined education as the kindling of a flame, not the filling of a vessel. Socrates also defines education as midwifery for the soul.", "Dewey: education is not a preparation for life; it is life itself."], "type": "list"}, {"correct_index": 1, "explanation": "Socrates defined education as the kindling of a flame, not the filling of a vessel.", "options": ["Plato", "Socrates", "Aristotle"], "question": "Who defined education as the kindling of a flame, not the filling of a vessel?", "type": "checkpoint"}]}, {"title": "Branches and the meaning of philosophy", "objective": "Explain the major branches of philosophy and distinguish accounts of knowledge and consciousness.", "blocks": [{"type": "heading", "level": 2, "text": "The meaning of philosophy"}, {"type": "paragraph", "text": "Philosophy examines fundamental questions about reality, knowledge, reasoning and values. Its name is commonly translated as love of wisdom."}, {"type": "heading", "level": 2, "text": "Epistemology"}, {"type": "paragraph", "text": "Epistemology studies the nature, sources and limits of knowledge. It asks how beliefs are justified and how knowledge differs from opinion."}, {"type": "heading", "level": 2, "text": "Political philosophy"}, {"type": "paragraph", "text": "Political philosophy examines justice, rights, legitimate authority and how societies should be organised."}, {"type": "heading", "level": 2, "text": "Aesthetics"}, {"type": "paragraph", "text": "Aesthetics studies beauty, art and aesthetic experience, including how we interpret and evaluate works of art."}, {"type": "heading", "level": 2, "text": "Logic"}, {"type": "paragraph", "text": "Logic studies reasoning and the conditions under which conclusions follow from premises. It helps distinguish valid arguments from invalid ones."}, {"type": "heading", "level": 2, "text": "Speculative and prescriptive philosophy"}, {"type": "paragraph", "text": "Speculative philosophy seeks a broad understanding of reality and how its parts fit together. Prescriptive philosophy considers the standards and values that should guide action."}, {"type": "heading", "level": 2, "text": "Justified true belief"}, {"type": "paragraph", "text": "JTB means justified true belief. In this traditional account, a person must believe a claim, the claim must be true, and the person must have justification for it. Gettier cases show why meeting these three conditions may still be insufficient for knowledge."}, {"type": "heading", "level": 2, "text": "The Gettier problem"}, {"type": "paragraph", "text": "Edmund Gettier’s 1963 paper is titled Is Justified True Belief Knowledge? It presents cases in which a belief is justified and true but is true through luck rather than knowledge."}, {"type": "heading", "level": 2, "text": "Panpsychism"}, {"type": "paragraph", "text": "Panpsychism treats mentality as a fundamental and widespread feature of reality. It does not mean that every object thinks in the same way as a human being."}, {"type": "heading", "level": 2, "text": "Dualism"}, {"type": "paragraph", "text": "Mind–body dualism holds that the mental and the physical are distinct in a fundamental respect. Substance dualism treats minds and bodies as distinct kinds of substance."}, {"type": "heading", "level": 2, "text": "Emergence"}, {"type": "paragraph", "text": "Emergent accounts of consciousness explain conscious experience in relation to the organisation and interactions of physical systems, such as the brain. Different accounts disagree about whether consciousness can be reduced to those physical processes."}, {"type": "checkpoint", "question": "Which branch of philosophy studies knowledge?", "options": ["Epistemology", "Aesthetics", "Political philosophy", "Logic"], "correct_index": 0, "explanation": "Epistemology studies knowledge, its justification, sources and limits."}, {"type": "checkpoint", "question": "What does JTB stand for?", "options": ["Justified true belief", "Judgment through behaviour", "Justice, truth and beauty", "Joint theory of being"], "correct_index": 0, "explanation": "JTB abbreviates justified true belief."}]}, {"title": "Bloom's taxonomy", "objective": "Recall the six cognitive categories, the affective domain, and the six psychomotor categories from the answer key.", "blocks": [{"text": "Bloom’s taxonomy classifies educational objectives. The cognitive domain concerns thinking, the affective domain concerns values and attitudes, and the psychomotor domain concerns physical skills.", "type": "paragraph"}, {"level": 2, "text": "Cognitive domain", "type": "heading"}, {"text": "There are six categories under the cognitive domain: knowledge, comprehension, application, analysis, synthesis and evaluation.", "type": "paragraph"}, {"items": ["Knowledge is the ability to recall data and information.", "Comprehension is understanding the meaning of what is known.", "Application is the ability to utilise an abstraction or to use knowledge in a new situation.", "Analysis is the ability to differentiate facts and opinions.", "Synthesis integrates elements to form a sound pattern or structure to establish a new meaning.", "Evaluation is the ability to come up with judgements about the importance of concepts."], "type": "list"}, {"level": 2, "text": "Affective domain", "type": "heading"}, {"text": "The affective domain involves feelings, emotions and attitude. It is categorised into five sub-domains: receiving, responding, valuing, organisation and characterisation.", "type": "paragraph"}, {"level": 2, "text": "Psychomotor domain", "type": "heading"}, {"text": "The psychomotor domain was thoroughly described in the 1970s. There are six categories: perception, set, guided response, mechanism, adaptation and origination.", "type": "paragraph"}, {"correct_index": 0, "explanation": "Knowledge is the ability to recall data and information.", "options": ["Knowledge", "Comprehension", "Application"], "question": "Which category is the ability to recall data and information?", "type": "checkpoint"}]}, {"title": "Behaviourism", "objective": "Distinguish classical and operant conditioning and explain how reinforcement affects behaviour.", "blocks": [{"type": "heading", "level": 2, "text": "Behaviourism"}, {"type": "paragraph", "text": "Behaviourism studies learning through observable behaviour and its relationship with the environment."}, {"type": "heading", "level": 2, "text": "Classical conditioning"}, {"type": "paragraph", "text": "Classical conditioning involves learning an association between stimuli. A previously neutral stimulus can come to trigger a response after being repeatedly paired with a stimulus that already produces that response."}, {"type": "heading", "level": 2, "text": "Operant conditioning"}, {"type": "paragraph", "text": "Operant conditioning involves learning through the consequences of behaviour. Reinforcement makes a behaviour more likely, while punishment makes it less likely."}, {"type": "heading", "level": 2, "text": "Learning in the classroom"}, {"type": "paragraph", "text": "Teachers can encourage learning with clear expectations, feedback, practice and reinforcement. The effect of a consequence depends on how it changes the learner’s behaviour."}, {"type": "checkpoint", "question": "What is the effect of reinforcement on a behaviour?", "options": ["It makes the behaviour more likely.", "It always removes the behaviour.", "It prevents every response.", "It has no relationship to behaviour."], "correct_index": 0, "explanation": "Reinforcement increases the likelihood that a behaviour will occur again."}]}, {"title": "Head, heart and hand", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Head, heart and hand", "type": "heading"}, {"text": "Wholistic education connects intellectual, emotional, physical and spiritual development. The notes use head for mental abilities and thinking, heart for values and motives, and hand for practical skills and useful work. These aspects support one another: understanding should inform conduct and practical action. Within the religious framework of the notes, the purpose includes service and the development of the whole person.", "type": "paragraph"}, {"text": "Planning a community garden uses reasoning to design it, cooperation to work responsibly and practical skill to plant it.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 2, "explanation": "Mental faculties and thinking power.", "options": ["Emotional intelligence and empathy", "Physical health and fitness", "Mental faculties and thinking power", "Spiritual discernment and wisdom"], "question": "Education of the “Head” primarily focuses on:", "type": "checkpoint"}]}, {"title": "Character, service and independent thought", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Character, service and independent thought", "type": "heading"}, {"text": "The supplied notes connect whole-person education with character, service and the capacity to think independently. In their Christian framework, restoration of God's image describes an educational purpose rather than an academic grading method. Learners are encouraged to exercise judgement instead of repeating another person's thoughts without understanding. This aim links intellectual development with values and responsible action.", "type": "paragraph"}, {"text": "A student gives reasons for a decision, listens to criticism and revises the decision where the evidence warrants it.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 2, "explanation": "Restoring God’s image in humanity.", "options": ["Wealth accumulation", "Political power", "Restoring God’s image in humanity", "Scientific discovery"], "question": "The great object of education and life is:", "type": "checkpoint"}]}, {"title": "Christian curriculum and educational settings", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Christian curriculum and educational settings", "type": "heading"}, {"text": "The notes present Christian curriculum through examples drawn from Eden, Israelite education and schools of the prophets. In that framework, nature study, moral instruction and useful work belong together. Parents have an educational role, and practical preparation accompanies religious learning. These are the theological and historical examples used in the supplied question bank; they help explain its conception of integrated education.", "type": "paragraph"}, {"text": "A curriculum can connect an observation of nature, discussion of responsibility and a practical task instead of treating these as unrelated activities.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 1, "explanation": "God as Teacher and nature as lesson book.", "options": ["Structured classroom instruction", "God as Teacher and nature as lesson book", "Formal curriculum and examinations", "Professional educational administrators"], "question": "The Edenic school established by God featured:", "type": "checkpoint"}]}, {"title": "Teachers, diligence and discernment", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Teachers, diligence and discernment", "type": "heading"}, {"text": "The Christian curriculum notes connect teaching with the teacher's own values and conduct. Diligent teaching requires effort, perseverance and commitment. Discernment means judging carefully, while critical thought examines reasons and avoids blind acceptance of authority. Integration of faith and learning therefore concerns both curriculum content and the way teachers guide, demonstrate and discuss ideas within this religious educational model.", "type": "paragraph"}, {"text": "When comparing explanations, a teacher asks students to identify the claim, examine its reasons and explain why a conclusion follows.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 1, "explanation": "Effort, perseverance, and commitment to excellence.", "options": ["Occasional instruction", "Effort, perseverance, and commitment to excellence", "Casual conversation about religious topics", "Infrequent religious discussions"], "question": "Teaching “diligently” involves:", "type": "checkpoint"}]}, {"title": "Truth, knowledge and sources of understanding", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Truth, knowledge and sources of understanding", "type": "heading"}, {"text": "Epistemology studies knowledge, including its sources, scope and justification. Correspondence accounts connect truth with how things are; coherence accounts stress consistency within a body of beliefs; pragmatic accounts connect truth with practical inquiry and its consequences. Rationalism emphasises reason, while empiricism emphasises experience. These positions differ in emphasis and should not be reduced to the claim that every belief which feels useful is true.", "type": "paragraph"}, {"text": "A claim that a window is open can be checked against the window. That illustrates correspondence between a statement and the situation it describes.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 1, "explanation": "Agreement between statement and actual state of affairs.", "options": ["What works in practice", "Agreement between statement and actual state of affairs", "Consistency with other accepted judgments", "Socially constructed consensus"], "question": "The correspondence theory of truth states that truth is:", "type": "checkpoint"}]}, {"title": "Logical connectives and common fallacies", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Logical connectives and common fallacies", "type": "heading"}, {"text": "For ordinary two-valued logic, a conjunction is true only when both components are true. An inclusive disjunction is false only when both are false. The law of non-contradiction rules out a proposition and its negation both being true at the same time and in the same respect. An ad hominem attacks the person instead of the argument; ad populum substitutes popularity for reasons; ad baculum relies on force or threats.", "type": "paragraph"}, {"text": "A proposal is not proved correct because many people support it, nor refuted merely by insulting the proposer. Evaluate the claim and evidence.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 0, "explanation": "Both input statements are true.", "options": ["Both input statements are true", "At least one input statement is true", "Both input statements are false", "The first statement is true"], "question": "In truth tables, the conjunction connective “AND” is true only when:", "type": "checkpoint"}]}, {"title": "Idealism and the education of the mind", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Idealism and the education of the mind", "type": "heading"}, {"text": "The notes associate idealism with the importance of mind or spirit in understanding reality. Their educational discussion stresses intellectual and moral development. Plato's cave illustrates a movement from ignorance toward understanding. Descartes' cogito connects thinking with certainty of one's existence as a thinker. Kant distinguishes phenomena as experienced from things considered in themselves, or noumena. These philosophers differ substantially, so the chapter labels should be used as an introductory comparison.", "type": "paragraph"}, {"text": "Comparing an appearance with a reasoned explanation illustrates why an educator might ask students to look beyond an initial impression.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 1, "explanation": "Mental or spiritual in nature.", "options": ["Material and physical", "Mental or spiritual in nature", "Socially constructed", "Scientifically measurable only"], "question": "Idealism posits that reality is fundamentally:", "type": "checkpoint"}]}, {"title": "Realism, inquiry and faith and reason", "objective": "Explain the main distinctions and apply them to an example.", "blocks": [{"level": 2, "text": "Realism, inquiry and faith and reason", "type": "heading"}, {"text": "Realism affirms a reality independent of human perception. The notes connect realist education with disciplined inquiry and observation, including Bacon's emphasis on induction. They also discuss Aquinas and the relationship between Aristotelian philosophy and Christian theology. In that account, reason and faith have complementary roles. Compare educational approaches by their views of reality, knowledge and purpose instead of assuming that every thinker within a broad school holds an identical position.", "type": "paragraph"}, {"text": "Students investigate an object, record observations and compare explanations. This reflects an emphasis on inquiry into a world that exists independently of their preferences.", "title": "Apply the idea", "tone": "example", "type": "callout"}, {"correct_index": 1, "explanation": "Independently of human perception.", "options": ["Only in the mind", "Independently of human perception", "As social construction only", "Through divine revelation exclusively"], "question": "Realism asserts that reality exists:", "type": "checkpoint"}]}]$content$::jsonb) loop
  for v_lesson in select l.id from public.lessons l join public.courses c on c.id=l.course_id
   where c.code='AUE-GST 201' and exists(select 1 from public.lesson_versions lv where lv.lesson_id=l.id and lv.title=v_row->>'title')
  loop
   select * into v_old from public.lesson_versions where lesson_id=v_lesson order by version desc limit 1;
   if v_old.blocks=v_row->'blocks' and v_old.objective=v_row->>'objective' then continue; end if;
   if v_old.status='draft' then
    update public.lesson_versions set blocks=v_row->'blocks',objective=v_row->>'objective' where id=v_old.id;
   else
    insert into public.lesson_versions(lesson_id,version,title,objective,blocks,estimated_minutes,source_reference)
    values(v_lesson,v_old.version+1,v_old.title,v_row->>'objective',v_row->'blocks',v_old.estimated_minutes,
    'Reviewed lesson notes; OpenStax Introduction to Philosophy; OpenStax Psychology 6.1; https://plato.stanford.edu/entries/knowledge-analysis/; https://plato.stanford.edu/entries/panpsychism/') returning id into v_new;
    if v_actor is not null and v_old.status='published' then perform private.publish_lesson_version(v_new,v_actor); end if;
   end if;
  end loop;
 end loop;
end;
$migration$;
